-- Idempotent install for public.root_causes
-- Auto-generated from dbanalytics_install.backup. Safe to re-run (psql -f).

CREATE SCHEMA IF NOT EXISTS public;

CREATE SEQUENCE IF NOT EXISTS public.root_causes_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE IF NOT EXISTS public.root_causes (
    id integer NOT NULL,
    root_cause_id character varying(40) NOT NULL,
    issue_id integer NOT NULL,
    root_cause_number smallint NOT NULL,
    name character varying(300) NOT NULL,
    description text,
    topics text[],
    vendors_applicable text[] DEFAULT '{}'::text[] NOT NULL,
    vendor_considerations jsonb,
    search_text jsonb,
    vendor_descriptions jsonb
);

ALTER TABLE public.root_causes ALTER COLUMN id SET DEFAULT nextval('public.root_causes_id_seq'::regclass);
ALTER SEQUENCE public.root_causes_id_seq OWNED BY public.root_causes.id;

-- data: load only into a freshly-created (empty) table
DROP TABLE IF EXISTS _stg_load;
CREATE TEMP TABLE _stg_load (LIKE public.root_causes);
SELECT id, root_cause_id, issue_id, root_cause_number, name, description, topics, vendors_applicable, vendor_considerations, search_text, vendor_descriptions FROM _stg_load
WHERE NOT EXISTS (SELECT 1 FROM public.root_causes);
DROP TABLE _stg_load;

SELECT setval('public.root_causes_id_seq', GREATEST((SELECT COALESCE(max(id),0) FROM public.root_causes),1), (SELECT count(*) FROM public.root_causes) > 0);

DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = 'root_causes'
          AND con.conname = 'root_causes_issue_id_root_cause_number_key') THEN
        ALTER TABLE ONLY public.root_causes
    ADD CONSTRAINT root_causes_issue_id_root_cause_number_key UNIQUE (issue_id, root_cause_number);
    END IF;
END $do$;
DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = 'root_causes'
          AND con.conname = 'root_causes_pkey') THEN
        ALTER TABLE ONLY public.root_causes
    ADD CONSTRAINT root_causes_pkey PRIMARY KEY (id);
    END IF;
END $do$;
DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = 'root_causes'
          AND con.conname = 'root_causes_root_cause_id_key') THEN
        ALTER TABLE ONLY public.root_causes
    ADD CONSTRAINT root_causes_root_cause_id_key UNIQUE (root_cause_id);
    END IF;
END $do$;

CREATE INDEX IF NOT EXISTS idx_root_causes_issue ON public.root_causes USING btree (issue_id);
CREATE INDEX IF NOT EXISTS idx_root_causes_topics ON public.root_causes USING gin (topics);
CREATE INDEX IF NOT EXISTS idx_root_causes_vendors ON public.root_causes USING gin (vendors_applicable);
